{ echo sb_rowD7f; cat $R/sb_queue/queue.txt; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; cat $R/sb_queue/queue.txt | tr "\n" " "; echo; tail -2 $R/sb_queue/codexq.log
pgrep -af "codex_dispatch.sh implement $R/sb_" | grep -o "label [a-zA-Z0-9_]*" | sort -u | tr "\n" " "; echo
